function check(input, actual, expected) {
  const nums = input[0];
  if (!Array.isArray(actual) || actual.length !== nums.length) return false;
  const got = [...actual].sort((a, b) => a - b);
  const want = [...nums].sort((a, b) => a - b);
  if (got.some((v, i) => v !== want[i])) return false;
  let seenOdd = false;
  for (const v of actual) {
    if (v % 2 !== 0) seenOdd = true;
    else if (seenOdd) return false;
  }
  return true;
}

